const installationsForRepo = `-- name: InstallationsForRepo :many
SELECT i.id, i.num_id, i.permissions, i.events, a.id AS app_id, a.num_id AS app_num_id, w.id AS webhook_id
FROM app_installations i
JOIN repos r ON r.id = $1 AND r.owner_id = i.account_id
JOIN apps a ON a.id = i.app_id
JOIN webhooks w ON w.app_id = a.id AND w.active
WHERE i.suspended_at IS NULL
  AND (i.repository_selection = 'all'
       OR EXISTS (SELECT 1 FROM app_installation_repos ir WHERE ir.installation_id = i.id AND ir.repo_id = r.id))
ORDER BY i.num_id
`

type InstallationsForRepoRow struct {
	ID          uuid.UUID
	NumID       pgtype.Int8
	Permissions []byte
	Events      []string
	AppID       uuid.UUID
	AppNumID    pgtype.Int8
	WebhookID   uuid.UUID
}

// Active installations covering a repository, with the webhook of their app
// (for event deliveries).
func (q *Queries) InstallationsForRepo(ctx context.Context, repoID uuid.UUID) ([]InstallationsForRepoRow, error) {
	rows, err := q.db.Query(ctx, installationsForRepo, repoID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []InstallationsForRepoRow{}
	for rows.Next() {
		var i InstallationsForRepoRow
		if err := rows.Scan(
			&i.ID,
			&i.NumID,
			&i.Permissions,
			&i.Events,
			&i.AppID,
			&i.AppNumID,
			&i.WebhookID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

