const listUserOwnedOrgs = `-- name: ListUserOwnedOrgs :many
SELECT n.id, n.name FROM org_members m
JOIN namespaces n ON n.id = m.org_id
WHERE m.user_id = $1 AND m.role = 'owner'
ORDER BY n.name_lower
`

type ListUserOwnedOrgsRow struct {
	ID   uuid.UUID
	Name string
}

func (q *Queries) ListUserOwnedOrgs(ctx context.Context, userID uuid.UUID) ([]ListUserOwnedOrgsRow, error) {
	rows, err := q.db.Query(ctx, listUserOwnedOrgs, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUserOwnedOrgsRow{}
	for rows.Next() {
		var i ListUserOwnedOrgsRow
		if err := rows.Scan(&i.ID, &i.Name); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

